local config = {
  ui_story_5041_50410101_1_dialog_content = "Luke, tem um pacote para você!",
  ui_story_5041_50410101_2_dialog_content = "PlayerName? Por que você está entregando?",
  ui_story_5041_50410101_3_dialog_content = "E quem é esse?",
  ui_story_5041_50410101_4_dialog_content = "Aqui é Lady Jeriah do Courier Union. Só estou ajudando no Mooncrown Day.",
  ui_story_5041_50410101_5_dialog_content = "Olá, vice-comandante dos Mercenários da Chama Branca. Sua reputação o precede.",
  ui_story_5041_50410101_6_dialog_content = "Um membro sênior do Courier Union? Uma honra conhecê-lo. Mas quem me enviaria um pacote?",
  ui_story_5041_50410101_7_dialog_content = "Por que você não abre? Devemos dar-lhe alguma privacidade?",
  ui_story_5041_50410101_8_dialog_content = "Não há necessidade. Se for uma ameaça de um inimigo, precisarei de mais informações suas.",
  ui_story_5041_50410101_9_dialog_content = "Você não é um pouco cauteloso demais? Uma embalagem tão delicada não poderia ser de um rival.",
  ui_story_5041_50410101_10_dialog_content = "Hmm, há uma nota anexada dentro da caixa.",
  ui_story_5041_50410101_11_dialog_content = "\"Comandante Luke, desculpe me comunicar com você desta forma, mas a missão vem primeiro, então devemos confiar na correspondência.\"",
  ui_story_5041_50410101_12_dialog_content = "\"Todos nós testemunhamos em primeira mão seu senso de dever para com os Mercenários da Chama Branca e consideração por todos.\"",
  ui_story_5041_50410101_13_dialog_content = "\"Tudo o que fazemos é cumprir as missões, mas você deve pensar no futuro da organização e como expandi-la...\"",
  ui_story_5041_50410101_14_dialog_content = "\"Você também se preocupa com o bem-estar de todos os membros nos mínimos detalhes. Muitas vezes brincamos e dizemos que você é onipotente.\"",
  ui_story_5041_50410101_15_dialog_content = "\"No entanto, eu sei que você também é uma pessoa normal, e carregar tanto por tanto tempo o deixa cansado às vezes.\"",
  ui_story_5041_50410101_16_dialog_content = "É deles... Eu disse para eles não me chamarem de \"comandante\". Não posso acreditar que eles arranjaram tempo para escrever isso no meio de uma missão.",
  ui_story_5041_50410101_17_dialog_content = "Isso é muito comovente. Acho que seus mercenários se importam muito com você.",
  ui_story_5041_50410101_18_dialog_content = "Isso porque Luke é uma pessoa muito responsável, fato óbvio para todos.",
  ui_story_5041_50410101_19_dialog_content = "O que mais a carta diz?",
  ui_story_5041_50410101_20_dialog_content = "\"Você acorda cedo e vai dormir tarde todas as noites, então reservamos um tempo para fazer uma bolsa de ervas para você.\"",
  ui_story_5041_50410101_21_dialog_content = "\"Ouvimos dizer que essas ervas podem ajudar a dormir. Por favor, experimente na próxima vez que dormir, colocando-as ao lado do travesseiro.\"",
  ui_story_5041_50410101_22_dialog_content = "\"Esperamos que você também possa tirar uma soneca de vez em quando.\"",
  ui_story_5041_50410101_23_dialog_content = "\"De, seus mercenários.\"",
  ui_story_5041_50410101_24_dialog_content = "Fazendo tudo isso em uma missão... Eu só estava fazendo o que deveria fazer, na verdade.",
  ui_story_5041_50410101_25_dialog_content = "Eu certamente não esperava isso.",
  ui_story_5041_50410101_26_dialog_content = "Sim, Luke, devias ir com calma de vez em quando. Você está propenso a erros se estiver sempre tenso.",
  ui_story_5041_50410101_27_dialog_content = "O descanso adequado é essencial para concluir cada nova tarefa que surge em nosso caminho... Acho que eles estão certos.",
  ui_story_5041_50410101_28_dialog_content = "Como todos parecem estar dizendo a mesma coisa, seguirei o conselho.",
  ui_story_5041_50410101_29_dialog_content = "Assim que terminar hoje, vou tirar uma soneca com a bolsa ao lado do meu travesseiro.",
  ui_story_5041_50410201_1_dialog_content = "Huff, huff... Aí está você, Comandante Hiiro!",
  ui_story_5041_50410201_2_dialog_content = "PlayerName?",
  ui_story_5041_50410201_3_dialog_content = "O que você está fazendo aqui? Aconteceu alguma coisa em Illumina?!",
  ui_story_5041_50410201_4_dialog_content = "Não, estou apenas entregando correspondência com Jeriah da Courier Union. Aqui, um pacote para você, bem pesado também.",
  ui_story_5041_50410201_5_dialog_content = "Heh, acho que o remetente é interessante.",
  ui_story_5041_50410201_6_dialog_content = "Estranho, quem enviaria um pacote para mim aqui na linha de frente?",
  ui_story_5041_50410201_7_dialog_content = "Isso é normal. Afinal, é o Dia da Coroa da Lua.",
  ui_story_5041_50410201_8_dialog_content = "Dia da coroa lunar? Ah, certo... eu esqueci completamente.",
  ui_story_5041_50410201_9_dialog_content = "Estou sem tempo, então vamos ver o que tem dentro... Espere, deixe-me ver quem mandou primeiro.",
  ui_story_5041_50410201_10_dialog_content = "Ah, é da Zoya. Estes são...",
  ui_story_5041_50410201_11_dialog_content = "Pãezinhos de serragem, carne enlatada, creme de cogumelos, grãos de chocolate e até rolinhos de canela.",
  ui_story_5041_50410201_12_dialog_content = "São todas especialidades Illumina.",
  ui_story_5041_50410201_13_dialog_content = "Eu acredito que é uma tradição para os amantes da Illumina presentear rolos de canela feitos à mão. Muito romântico.",
  ui_story_5041_50410201_14_dialog_content = "Provavelmente não foi intencional da parte de Zoya.",
  ui_story_5041_50410201_15_dialog_content = "(De alguma forma, não acho que foi intencional.)",
  ui_story_5041_50410201_16_dialog_content = "Acho que tem algo escrito na caixa.",
  ui_story_5041_50410201_17_dialog_content = "\"Senhora Hiiro, obrigado por seu trabalho na linha de frente! Ouvi dizer que você ficaria longe por muito tempo. Só posso imaginar o quão cansativo será.\"",
  ui_story_5041_50410201_18_dialog_content = "\"Imagino que você esteja desejando iguarias Illumina, então pedi a vovó para preparar um pacote de cuidados.\"",
  ui_story_5041_50410201_19_dialog_content = "\"Mas eu mesmo fiz os rolinhos de canela, então certifique-se de provar isso primeiro!\"",
  ui_story_5041_50410201_20_dialog_content = "(Posso imaginar a expressão no rosto de Zoya.)",
  ui_story_5041_50410201_21_dialog_content = "\"Lady Hiiro, eu adoraria passar o Mooncrown Day com você, mas a linha de frente é a prioridade, então, por favor, cuide-se!\"",
  ui_story_5041_50410201_22_dialog_content = "\"Meu coração e minha alma pertencem a você, minha linda, forte e legal Lady Hiiro!\"",
  ui_story_5041_50410201_23_dialog_content = "Uma pessoa que pode ler uma frase como essa em voz alta com uma cara séria é verdadeiramente extraordinária.",
  ui_story_5041_50410201_24_dialog_content = "Ahaha, concordo.",
  ui_story_5041_50410201_25_dialog_content = "Eu aprecio os pensamentos de Zoya e certamente sinto falta da comida Illumina.",
  ui_story_5041_50410201_26_dialog_content = "Ela é sempre tão carinhosa. Tenho certeza de que todos no laboratório de pesquisa também gostam dela.",
  ui_story_5041_50410201_27_dialog_content = "Acho que ela só se importa com você...",
  ui_story_5041_50410201_28_dialog_content = "Já que ela mesma fez os rolinhos de canela, vou dar uma mordida.",
  ui_story_5041_50410201_29_dialog_content = "*mastiga*",
  ui_story_5041_50410201_30_dialog_content = "Milímetros. Eu realmente posso provar os sentimentos de Zoya com isso.",
  ui_story_5041_50410201_31_dialog_content = "(Vou garantir um palpite de que o gosto é muito questionável...)",
  ui_story_5041_50410201_32_dialog_content = "Obrigado por entregar isso à linha de frente. Por que vocês dois não passam a noite? Podemos festejar com esta comida juntos.",
  ui_story_5041_50410201_33_dialog_content = "Claro, estou bastante interessado na comida Illumina.",
  ui_story_5041_50410201_34_dialog_content = "Ei, ainda temos mais correspondência para entregar!",
  ui_story_5041_50410301_1_dialog_content = "Novio, tenho um pacote para você!",
  ui_story_5041_50410301_2_dialog_content = "Fomos primeiro ao Palácio de Inverno, mas, surpreendentemente, você não estava lá.",
  ui_story_5041_50410301_3_dialog_content = "Só estou aqui dando um passeio. Eu não esperava que você fosse o mensageiro, PlayerName.",
  ui_story_5041_50410301_4_dialog_content = "Eu vim com Jeriah, então estou apenas ajudando.",
  ui_story_5041_50410301_5_dialog_content = "A paisagem em Northland é sempre espetacular, não importa quantas vezes eu tenha estado aqui.",
  ui_story_5041_50410301_6_dialog_content = "Está isolado do resto do continente, quase em seu próprio mundo. Eu espero que você goste disso aqui.",
  ui_story_5041_50410301_7_dialog_content = "Oh sim, aqui está o seu pacote. É da Lola!",
  ui_story_5041_50410301_8_dialog_content = "Lola? Se bem me lembro, ela não tem estado em Northland ultimamente.",
  ui_story_5041_50410301_9_dialog_content = "Ela parece ter visitado muitos lugares. Suas bochechas estavam todas vermelhas de excitação.",
  ui_story_5041_50410301_10_dialog_content = "Dada a sua personalidade, ela provavelmente se divertiu muito saboreando lanches e bugigangas locais.",
  ui_story_5041_50410301_11_dialog_content = "De qualquer forma, deixe-me dar uma olhada lá dentro...",
  ui_story_5041_50410301_12_dialog_content = "Chocolate em forma de Eclipsites?",
  ui_story_5041_50410301_13_dialog_content = "Isso parece muito... autêntico.",
  ui_story_5041_50410301_14_dialog_content = "Há uma nota também.",
  ui_story_5041_50410301_15_dialog_content = "\"Novio, dê uma olhada neste chocolate com sabor de Eclipsite que encontrei em uma loja de doces Umbraton. Você precisa experimentar!\"",
  ui_story_5041_50410301_16_dialog_content = "Tenho dificuldade em imaginar como seria o sabor dos Eclipsites.",
  ui_story_5041_50410301_17_dialog_content = "Bem, há sempre um primeiro para tudo.",
  ui_story_5041_50410301_18_dialog_content = "E o que tem nessa caixa preta... Uau!",
  ui_story_5041_50410301_19_dialog_content = "A-Tá tudo bem, Novio?",
  ui_story_5041_50410301_20_dialog_content = "Este é um daqueles brinquedos jack-in-the-box? Isso me assustou.",
  ui_story_5041_50410301_21_dialog_content = "Esta cabeça lembra um pouco uma certa pessoa...",
  ui_story_5041_50410301_22_dialog_content = "Sou só eu ou parece o Sinsa?",
  ui_story_5041_50410301_23_dialog_content = "É um design divertido, mas devo guardá-lo.",
  ui_story_5041_50410301_24_dialog_content = "\"Entrei em um leilão em um mercado no deserto e não pude acreditar que ninguém deu lances neste brinquedo legal, então comprei!\"",
  ui_story_5041_50410301_25_dialog_content = "\"Acho que foi inspirado em alguém, mas não faço ideia de quem.\"",
  ui_story_5041_50410301_26_dialog_content = "Eu nem sabia que esses mercados vendiam essas coisas. Quão único.",
  ui_story_5041_50410301_27_dialog_content = "Ele se encaixa no estilo de Lola, tudo bem.",
  ui_story_5041_50410301_28_dialog_content = "Esperemos que não haja mais surpresas nesta caixa... São flores secas?",
  ui_story_5041_50410301_29_dialog_content = "Eles são tão bonitos...",
  ui_story_5041_50410301_30_dialog_content = "\"Eu colecionei durante minha viagem. Elas incluem minhas rosas silvestres favoritas e algumas outras que não reconheço.\"",
  ui_story_5041_50410301_31_dialog_content = "\"Eu os pressionei em marcadores. Você gosta de ler, então acho que vai achá-los úteis!\"",
  ui_story_5041_50410301_32_dialog_content = "\"Se você descobriu que flores são, me avise!\"",
  ui_story_5041_50410301_33_dialog_content = "Ela é um espírito tão livre... E todas as flores são deslumbrantes.",
  ui_story_5041_50410301_34_dialog_content = "Eu acredito que estes são amaranto, lírio de palmeira e jasmim. Acho que vou ter que escrever de volta e contar a ela.",
  ui_story_5041_50410301_35_dialog_content = "Muito obrigado a ambos por entregar o pacote. Gostaria de experimentar o chocolate comigo?",
  ui_story_5041_50410301_36_dialog_content = "(Chocolate com sabor de Eclipse? Acho que vou passar.)",
  ui_story_5041_50410301_37_dialog_content = "Muito obrigado.",
  ui_story_5041_50410301_38_dialog_content = "Ei, não coma nada!",
  ui_story_5041_50410401_1_dialog_content = "Este deve ser o endereço... provavelmente?",
  ui_story_5041_50410401_2_dialog_content = "A escrita é tão ilegível que quase dói meus olhos para ler!",
  ui_story_5041_50410401_3_dialog_content = "Eu mal posso dizer que é endereçado a Harbour City, mas o resto é uma bagunça confusa...",
  ui_story_5041_50410401_4_dialog_content = "Será que estamos no lugar certo?",
  ui_story_5041_50410401_5_dialog_content = "Sim, este é o lugar certo.",
  ui_story_5041_50410401_6_dialog_content = "Como você tem tanta certeza, Jeriah?",
  ui_story_5041_50410401_7_dialog_content = "Olhe ali, não parece que essa pessoa está esperando pelo correio?",
  ui_story_5041_50410401_8_dialog_content = "Suspiro, vai estar aqui hoje? Estou meio cansado...",
  ui_story_5041_50410401_9_dialog_content = "Quando no mundo ela chegou lá?! Eu não a vi lá antes!",
  ui_story_5041_50410401_10_dialog_content = "Está falando de mim?",
  ui_story_5041_50410401_11_dialog_content = "Eu estive aqui o tempo todo, mas não me movi porque estou muito cansado.",
  ui_story_5041_50410401_12_dialog_content = "Não é à toa que não te vi...",
  ui_story_5041_50410401_13_dialog_content = "Vocês são os correios?",
  ui_story_5041_50410401_14_dialog_content = "Sim, estamos, mocinha.",
  ui_story_5041_50410401_15_dialog_content = "Isto é endereçado a Ni... Nina?",
  ui_story_5041_50410401_16_dialog_content = "É a Tina. Tee, não.",
  ui_story_5041_50410401_17_dialog_content = "Não me diga que você esqueceu meu nome?",
  ui_story_5041_50410401_18_option_content = "Eu conheço você!",
  ui_story_5041_50410401_19_dialog_content = "Era você quem estava procurando selos de Jeriah em Lumopolis, certo?",
  ui_story_5041_50410401_20_dialog_content = "Você se lembra de mim.",
  ui_story_5041_50410401_21_dialog_content = "Claro, tenho uma mente como uma armadilha de aço.",
  ui_story_5041_50410401_22_option_content = "Não sei...",
  ui_story_5041_50410401_23_dialog_content = "Então deixa eu me apresentar.",
  ui_story_5041_50410401_24_dialog_content = "Sou a Juíza Tina do Tribunal de Justiça em Lumopolis. Estou em Harbour City agora em negócios oficiais.",
  ui_story_5041_50410401_25_dialog_content = "Posso perguntar se isso é para mim?",
  ui_story_5041_50410401_26_dialog_content = "Parece que diz que o nome do destinatário é Tina.",
  ui_story_5041_50410401_27_dialog_content = "Desculpe, a escrita é muito difícil de entender.",
  ui_story_5041_50410401_28_dialog_content = "Eu não esperava ver alguém do Lumo Hall of Justice em Harbor City.",
  ui_story_5041_50410401_29_dialog_content = "Foi uma longa viagem, mas dormir em um dirigível foi uma experiência e tanto.",
  ui_story_5041_50410401_30_dialog_content = "O navio balançava suavemente ao vento, e o leito macio era como um berço.",
  ui_story_5041_50410401_31_dialog_content = "Eu conheço esse sentimento! É como quando vou para a cama no Colossus enquanto ele está no ar.",
  ui_story_5041_50410401_32_dialog_content = "Você tem bom gosto.",
  ui_story_5041_50410401_33_dialog_content = "Julgando pela sua roupa, você deve ser aquele que eles chamam de Navegador do Colosso? O Último Celestita?",
  ui_story_5041_50410401_34_dialog_content = "Er... meus títulos parecem cada vez mais sofisticados...",
  ui_story_5041_50410401_35_dialog_content = "Por que não me apresento?",
  ui_story_5041_50410401_36_dialog_content = "Eu sou realmente um celestita, mas apenas um celestita normal.",
  ui_story_5041_50410401_37_dialog_content = "Apenas me ligue PlayerName!",
  ui_story_5041_50410401_38_dialog_content = "PlayerName? Hmm, esse é um nome interessante.",
  ui_story_5041_50410401_39_dialog_content = "Estou ajudando o Courier Union a entregar correspondência agora. Comigo aqui está Jeriah.",
  ui_story_5041_50410401_40_dialog_content = "Olá!",
  ui_story_5041_50410401_41_dialog_content = "Que jovem adorável você é.",
  ui_story_5041_50410401_42_dialog_content = "De qualquer forma, por favor, assine aqui!",
  ui_story_5041_50410401_43_dialog_content = "Hmm, isso poderia ser \"aquilo\"...?",
  ui_story_5041_50410401_44_dialog_content = "<color=#e8d9bb>*sinal*</color>",
  ui_story_5041_50410401_45_dialog_content = "\"Que\"?",
  ui_story_5041_50410401_46_dialog_content = "Algo pelo qual tenho esperado todo esse tempo, desde que escrevi para aquele sujeito.",
  ui_story_5041_50410401_47_dialog_content = "Bem, deixe-me descobrir com certeza...",
  ui_story_5041_50410401_48_dialog_content = "<color=#e8d9bb>Rasgar-</color>",
  ui_story_5041_50410401_49_dialog_content = "Hã?",
  ui_story_5041_50410401_50_dialog_content = "Hum...",
  ui_story_5041_50410401_51_dialog_content = "Um saco de folhas? E dois frutos silvestres comestíveis ou não...",
  ui_story_5041_50410401_52_dialog_content = "T-As folhas estão podres... Elas não foram danificadas no transporte, foram?",
  ui_story_5041_50410401_53_dialog_content = "PlayerName, você verificou a condição do pacote quando o recebeu?",
  ui_story_5041_50410401_54_dialog_content = "Não...",
  ui_story_5041_50410401_55_dialog_content = "Eu vi este pacote na minha porta quando saí esta manhã.",
  ui_story_5041_50410401_56_dialog_content = "Quando olhei e vi que não era para mim, tratei como um pacote esperando ser entregue e trouxe comigo.",
  ui_story_5041_50410401_57_dialog_content = "Não é assim que funciona, Celestita.",
  ui_story_5041_50410401_58_dialog_content = "Você deve verificar o estado do conteúdo ao receber um pacote para saber que tipo de precauções são necessárias para entregá-lo.",
  ui_story_5041_50410401_59_dialog_content = "É uma parte básica de ser um mensageiro.",
  ui_story_5041_50410401_60_dialog_content = "Desculpe...",
  ui_story_5041_50410401_61_dialog_content = "Do que você está falando?",
  ui_story_5041_50410401_62_dialog_content = "Estas folhas não estão danificadas.",
  ui_story_5041_50410401_63_dialog_content = "Eles não são?",
  ui_story_5041_50410401_64_dialog_content = "Está vendo isso na folha? Não se parece com o Universese?",
  ui_story_5041_50410401_65_dialog_content = "Sim, agora que você mencionou!",
  ui_story_5041_50410401_66_dialog_content = "Mas está tão torto que quase não o reconheci.",
  ui_story_5041_50410401_67_dialog_content = "Acho que está escrito \"Obrigado\"?",
  ui_story_5041_50410401_68_dialog_content = "Estas não são folhas comuns. São papel de carta.",
  ui_story_5041_50410401_69_dialog_content = "Embora eu esteja feliz por conseguir isso, é uma pena.",
  ui_story_5041_50410401_70_dialog_content = "As folhas estão em ordem aleatória e a escrita é impossível de decifrar...",
  ui_story_5041_50410401_71_dialog_content = "Nem eu consigo decifrar tudo neles...",
  ui_story_5041_50410401_72_dialog_content = "É tão triste que não vou saber o que o carinha queria dizer.",
  ui_story_5041_50410401_73_dialog_content = "Mas é bom receber uma resposta, de qualquer maneira.",
  ui_story_5041_50410401_74_dialog_content = "Obrigado a ambos por entregá-lo.",
  ui_story_5041_50410401_75_dialog_content = "Quem é o garotinho de quem você fica falando?",
  ui_story_5041_50410401_76_dialog_content = "Parece um irmãozinho ou irmãzinha.",
  ui_story_5041_50410401_77_dialog_content = "Sim, você poderia chamá-los assim.",
  ui_story_5041_50410401_78_dialog_content = "Aquele sujeito é fofo como um gatinho e dá vontade de abraçá-lo.",
  ui_story_5041_50410401_79_dialog_content = "É um animal pequeno?",
  ui_story_5041_50410401_80_dialog_content = "É um segredo.",
  ui_story_5041_50410401_81_dialog_content = "Tudo bem, não vou me intrometer. Afinal, você tem direito à sua privacidade.",
  ui_story_5041_50410401_82_dialog_content = "Obrigado por escolher a Courier Union. Ansioso para atendê-lo na próxima vez!",
  ui_story_5041_50410401_83_dialog_content = "Certifique-se de confirmar a condição de qualquer pacote que você entregar também.",
  ui_story_5041_50410401_84_dialog_content = "Sim...",
  ui_story_5041_50410501_1_dialog_content = "Aqui está você, Eva!",
  ui_story_5041_50410501_2_dialog_content = "É você, PlayerName! E quem é esse?",
  ui_story_5041_50410501_3_dialog_content = "Olá, mocinha, sou Jeriah, da Courier Union.",
  ui_story_5041_50410501_4_dialog_content = "Oh, um mensageiro. Nunca vi ninguém da União antes.",
  ui_story_5041_50410501_5_dialog_content = "Olá, eu sou a Eva!",
  ui_story_5041_50410501_6_dialog_content = "Você recebeu correspondência, Eve!",
  ui_story_5041_50410501_7_dialog_content = "É do Sinsa.",
  ui_story_5041_50410501_8_dialog_content = "Meu irmão? Eu me pergunto o que ele me enviou.",
  ui_story_5041_50410501_9_dialog_content = "Provavelmente algo muito importante.",
  ui_story_5041_50410501_10_dialog_content = "Isto é o que ele disse quando nos entregou o pacote...",
  ui_story_5041_50410501_11_dialog_content = "Esta é uma entrega urgente para Eve. Certifique-se de que ela receba! Entendi?",
  ui_story_5041_50410501_12_dialog_content = "E-Entendi!",
  ui_story_5041_50410501_13_dialog_content = "É a primeira vez que ela sai de casa sozinha. Devo garantir a segurança dela e mantê-la longe dos bandidos.",
  ui_story_5041_50410501_14_dialog_content = "Eu estaria ao lado dela agora, protegendo-a de todos os perigos se ela não tivesse se recusado a me deixar acompanhá-la.",
  ui_story_5041_50410501_15_dialog_content = "Eva foi a algum lugar? Onde ela foi?",
  ui_story_5041_50410501_16_dialog_content = "Uma base localizada a várias centenas de metros de distância.",
  ui_story_5041_50410501_17_dialog_content = "Com certeza está longe...",
  ui_story_5041_50410501_18_dialog_content = "Claro que é! Apenas certifique-se de que ela receba este pacote muito importante!",
  ui_story_5041_50410501_19_dialog_content = "Suspiro... Ele ainda é tão superprotetor.",
  ui_story_5041_50410501_20_dialog_content = "Eu só queria experimentar sair por conta própria...",
  ui_story_5041_50410501_21_dialog_content = "Bem, acho que é uma bênção disfarçada ter alguém na família cuidando de você o tempo todo.",
  ui_story_5041_50410501_22_dialog_content = "Sim!",
  ui_story_5041_50410501_23_dialog_content = "Deixe-me ver o que meu irmão me enviou.",
  ui_story_5041_50410501_24_dialog_content = "Um caderno e... para que serve esta haste curva?",
  ui_story_5041_50410501_25_dialog_content = "Tanto quanto sei, é um pé de cabra.",
  ui_story_5041_50410501_26_dialog_content = "Você pode levantar coisas pesadas com ele e usá-lo para autodefesa em caso de emergência.",
  ui_story_5041_50410501_27_dialog_content = "Não me diga que Sinsa quer que você use isso como uma arma defensiva...",
  ui_story_5041_50410501_28_dialog_content = "Isso soa como ele...",
  ui_story_5041_50410501_29_dialog_content = "Vou ler o que está no caderno.",
  ui_story_5041_50410501_30_dialog_content = "\"Para Eve: Nunca saia com essas pessoas\"?",
  ui_story_5041_50410501_31_dialog_content = "É uma longa lista de nomes!",
  ui_story_5041_50410501_32_dialog_content = "Por que soa como uma lista negra?",
  ui_story_5041_50410501_33_dialog_content = "Quem está nisso?",
  ui_story_5041_50410501_34_dialog_content = "Deixe-me ver... O juiz de Lumopolis com presas de tubarão.",
  ui_story_5041_50410501_35_dialog_content = "Um pesquisador da Illumina apelidado de \"homem de meia-idade\".",
  ui_story_5041_50410501_36_dialog_content = "Um mercador de Umbraton que está sempre sorrindo.",
  ui_story_5041_50410501_37_dialog_content = "E O Último Celestita que anda por aí com o Colosso?",
  ui_story_5041_50410501_38_option_content = "Ei, sou eu!",
  ui_story_5041_50410501_39_dialog_content = "Por que Sinsa está me chamando de cara mau...?",
  ui_story_5041_50410501_40_dialog_content = "Isso é o que ele escreveu...",
  ui_story_5041_50410501_41_dialog_content = "\"PlayerName não é uma pessoa ruim, mas há uma coisa que você deve observar...\"",
  ui_story_5041_50410501_42_dialog_content = "\"A propensão para convencer os outros a correr o mundo com ele!\"",
  ui_story_5041_50410501_43_dialog_content = "Bem, isso é um fato.",
  ui_story_5041_50410501_44_dialog_content = "\"Se você não tomar cuidado, esquecerá o que deveria estar fazendo e logo se encontrará resolvendo uma crise em algum lugar.\"",
  ui_story_5041_50410501_45_dialog_content = "\"Então cuidado!\"",
  ui_story_5041_50410501_46_dialog_content = "Ele não te chamou de cara mau, PlayerName!",
  ui_story_5041_50410501_47_dialog_content = "Estou feliz com isso, mas...",
  ui_story_5041_50410501_48_dialog_content = "Isso ainda não se sente muito bem comigo de alguma forma ...",
  ui_story_5041_50410601_1_dialog_content = "Pacote expresso para você assinar, senhorita Azure!",
  ui_story_5041_50410601_2_dialog_content = "PlayerName? Você é o mensageiro desta vez?",
  ui_story_5041_50410601_3_dialog_content = "Muitas vezes você está cercado por pessoas tão interessantes.",
  ui_story_5041_50410601_4_dialog_content = "A-Tudo bem, sem provocações, por favor!",
  ui_story_5041_50410601_5_dialog_content = "Isso é da Zeta.",
  ui_story_5041_50410601_6_dialog_content = "Aquela criança parecia bastante imponente ao deixar o pacote.",
  ui_story_5041_50410601_7_dialog_content = "Ela disse-",
  ui_story_5041_50410601_8_dialog_content = "Velhos mensageiros que cavalgaram o dragão branco, o guerreiro solitário das dunas confia a você uma missão!",
  ui_story_5041_50410601_9_dialog_content = "Por favor, entregue isso ao lorde demônio azul que habita o Reino do Fogo.",
  ui_story_5041_50410601_10_dialog_content = "Como mensagem de determinação de uma guerreira!",
  ui_story_5041_50410601_11_dialog_content = "Acho que você é o lorde demônio azul de quem ela falou.",
  ui_story_5041_50410601_12_dialog_content = "Um lorde demônio de novo? Esse parece ser o meu papel permanente na cabeça dela.",
  ui_story_5041_50410601_13_dialog_content = "Bem, este tempo estava prestes a chegar.",
  ui_story_5041_50410601_14_dialog_content = "\"Desta vez\"? Por que você não parece nem um pouco surpreso?",
  ui_story_5041_50410601_15_dialog_content = "Vamos começar do começo.",
  ui_story_5041_50410601_16_dialog_content = "Desde aquela corrida de carros, Zeta começou a me desafiar.",
  ui_story_5041_50410601_17_dialog_content = "Ela me desafia em coisas diferentes quase a cada dez dias ou mais.",
  ui_story_5041_50410601_18_dialog_content = "Coisas como pedra-papel-tesoura, corridas, jogos de ação e assim por diante.",
  ui_story_5041_50410601_19_dialog_content = "Mas ela nunca ganhou.",
  ui_story_5041_50410601_20_dialog_content = "Isso parece ser muito...",
  ui_story_5041_50410601_21_dialog_content = "Brincar com uma garota interessante como ela também é divertido para mim.",
  ui_story_5041_50410601_22_dialog_content = "De qualquer forma, por favor, assine o pacote!",
  ui_story_5041_50410601_23_dialog_content = "Claro. Eu me pergunto o que ela está me desafiando desta vez.",
  ui_story_5041_50410601_24_dialog_content = "<color=#e8d9bb>*Rasgar*</color>",
  ui_story_5041_50410601_25_dialog_content = "Um pato?",
  ui_story_5041_50410601_26_dialog_content = "Isso é novo. Mas onde está o desafio?",
  ui_story_5041_50410601_27_dialog_content = "Acho que me lembro de algo.",
  ui_story_5041_50410601_28_dialog_content = "O pato é um gravador. Roy usou um para gravar a música de Regina antes.",
  ui_story_5041_50410601_29_dialog_content = "Deixe-me ver. Você pressiona aqui, eu acho.",
  ui_story_5041_50410601_30_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5041_50410601_31_dialog_content = "Ole lorde demônio azul do Reino do Fogo, o guerreiro solitário das dunas, desafia você!",
  ui_story_5041_50410601_32_dialog_content = "Demonstrarei minha determinação inabalável pela paz mundial e pela liberdade de todos os aurorianos.",
  ui_story_5041_50410601_33_dialog_content = "O tema deste desafio será: Heavy metal rock!",
  ui_story_5041_50410601_34_dialog_content = "Regina, companheira guerreira das dunas, julgará e tomará decisões justas.",
  ui_story_5041_50410601_35_dialog_content = "Se você perder, senhor demônio, você sofrerá uma punição severa...",
  ui_story_5041_50410601_36_dialog_content = "O bar não servirá bebidas por um mês inteiro!",
  ui_story_5041_50410601_37_dialog_content = "Porém, se o guerreiro perder...",
  ui_story_5041_50410601_38_dialog_content = "Vou punir meu eu patético não consumindo pirulitos por 30 dias!",
  ui_story_5041_50410601_39_dialog_content = "O tempo do desafio é definido para cinco dias após o envio desta carta. Esteja pronto para mim, senhor demônio!",
  ui_story_5041_50410601_40_dialog_content = "Puxa, parece que temos um verdadeiro desafio desta vez...",
  ui_story_5041_50410601_41_dialog_content = "Você não é bom em metal rock, Azure?",
  ui_story_5041_50410601_42_dialog_content = "Oh não, eu estava falando sobre a punição.",
  ui_story_5041_50410601_43_dialog_content = "Um mês inteiro sem bebida?",
  ui_story_5041_50410601_44_dialog_content = "Eu tenho que mostrar a esse garoto o quão bom eu sou!"
}
return config
